import java.util.*;
public class Main {
  public static void main(String[] args) {
    Scanner s=new Scanner(System.in);int n=s.nextInt(),k=s.nextInt();int[][] a=new int[n][n];for(int i=0;i<n;i++)for(int j=0;j<n;j++)a[i][j]=s.nextInt();int l=a[0][0],r=a[n-1][n-1];while(l<r){int m=l+(r-l)/2,count=0;for(int i=0;i<n;i++){int j=n-1;while(j>=0&&a[i][j]>m)j--;count+=j+1;}if(count>=k)r=m;else l=m+1;}System.out.println(l);
  }
}

